/** Public catalog owns role IDs and SVG mapping; components consume its generated snapshot. */
import fs from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";
const root = fileURLToPath(new URL("../", import.meta.url));
const catalog = JSON.parse(fs.readFileSync(path.join(root, "public/avatars/catalog.json"), "utf8"));
const source =
  "// Generated by frontend/scripts/build-avatar-manifest.mjs; edit public/avatars/catalog.json instead.\n" +
  `export const catalog = ${JSON.stringify(catalog)} as const;\n`;
const output = path.join(root, "src/lib/avatars/manifest.generated.ts");
if (!fs.existsSync(output) || fs.readFileSync(output, "utf8") !== source)
  fs.writeFileSync(output, source);
